//! Every older `PRIMASE_*` variable, for one release ([`crate::legacy`] translates each to its query; the
//! registry proper is [`crate::registry`]). The architecture test fails on a `PRIMASE_*` name in a source file that is
//! not declared here, and on an untranslated entry nothing reads. Descriptions are generic: no local paths.

/// What a variable is for.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    /// Real data a test reads (an install, a dump folder, a scene).
    Input,
    /// Narrows an input (a path or region filter).
    Filter,
    /// Where a test may write.
    Output,
    /// A behaviour flag or parameter.
    Switch,
    /// The configuration file itself.
    Config,
    /// An option a command reads (not a test).
    Runtime,
    /// A parent test's handoff to its own child process.
    Child,
    /// A made-up name in primase-testdata's own tests.
    Test,
}

/// One variable.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Variable {
    pub name: &'static str,
    pub kind: Kind,
    /// The landing gate must have it set (`PRIMASE_REQUIRE_REAL_DATA=gate`).
    pub gate: bool,
    /// What it is and the layout it must have.
    pub about: &'static str,
    /// Whether the obligation it serves stands.
    pub status: Status,
    /// Where its data comes from: the producer (a third-party reader and its version, the game itself, another
    /// exporter, our own earlier output) and so how far it is independent of what it checks. Empty for names that
    /// are not data.
    pub source: &'static str,
}

